:root {
  --ocean-deep: #0a3d62;
  --ocean-mid: #1a6b9a;
  --ocean-light: #5dade2;
  --foam: #eaf6fd;
  --sand: #f9e4b7;
  --sand-dark: #e8c87a;
  --coral: #e74c3c;
  --coral-light: #fadbd8;
  --sage: #27ae60;
  --sage-light: #d5f5e3;
  --amber: #f39c12;
  --amber-light: #fef9e7;
  --card-bg: #ffffff;
  --text-primary: #0a3d62;
  --text-muted: #7f8c8d;
  --border-light: #d6eaf8;
  --rating-bg: #0a3d62;
  --rating-text: #ffffff;
  --primary-block-bg: #eaf6fd;
  --primary-block-border: #5dade2;
}

.surf-card {
  background: var(--card-bg);
  border-radius: 16px;
  border: 2px solid var(--border-light);
  padding: 20px;
  max-width: 500px;
  width: 100%;
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.surf-header {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
}

.location-label {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 2px;
  color: var(--ocean-light);
  display: block;
}

.location-name {
  font-size: 22px;
  font-weight: 800;
  color: var(--text-primary);
  margin: 2px 0 0 0;
  line-height: 1.1;
}

.surf-rating {
  background: var(--rating-bg);
  border-radius: 10px;
  padding: 8px 14px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 2px;
}

.rating-score {
  font-size: 22px;
  font-weight: 900;
  color: var(--rating-text);
  line-height: 1;
}

.rating-label {
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 2px;
  color: var(--ocean-light);
}

.conditions-grid {
  display: grid;
  grid-template-columns: 1fr 1fr 1fr 1fr;
  gap: 8px;
}

.condition-block {
  background: var(--foam);
  border: 1px solid var(--border-light);
  border-radius: 10px;
  padding: 10px 8px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
}

.condition-block.primary {
  background: var(--primary-block-bg);
  border: 2px solid var(--primary-block-border);
}

.cond-value {
  font-size: 20px;
  font-weight: 800;
  color: var(--text-primary);
  line-height: 1;
}

.cond-unit {
  font-size: 12px;
  font-weight: 600;
  color: var(--ocean-light);
}

.cond-label {
  font-size: 10px;
  font-weight: 600;
  color: var(--text-muted);
  text-align: center;
  letter-spacing: 0.5px;
}

.tide-section {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.tide-title {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 2px;
  color: var(--text-muted);
}

.tide-bar-wrap {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.tide-bar {
  height: 10px;
  background: var(--border-light);
  border-radius: 6px;
  position: relative;
  overflow: visible;
}

.tide-fill {
  height: 100%;
  width: 60%;
  background: var(--ocean-light);
  border-radius: 6px;
}

.tide-marker {
  position: absolute;
  top: 50%;
  left: 60%;
  transform: translate(-50%, -50%);
  width: 14px;
  height: 14px;
  background: var(--ocean-deep);
  border: 2px solid var(--card-bg);
  border-radius: 50%;
}

.tide-labels {
  display: flex;
  justify-content: space-between;
  font-size: 10px;
  color: var(--text-muted);
  font-weight: 600;
}

.session-tags {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}

.tag {
  font-size: 11px;
  font-weight: 700;
  padding: 4px 10px;
  border-radius: 20px;
  letter-spacing: 0.3px;
}

.tag-expert {
  background: var(--coral-light);
  color: var(--coral);
}

.tag-reef {
  background: var(--sand);
  color: var(--sand-dark);
}

.tag-morning {
  background: var(--sage-light);
  color: var(--sage);
}

.tag-warning {
  background: var(--amber-light);
  color: var(--amber);
}
